-- Current internal-application identity never creates a person, operator or role.
CREATE TABLE ty_sso_profile(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 public_key text NOT NULL UNIQUE CHECK(public_key ~ '^[0-9a-f]{32}$'),
 group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),
 connection_id bigint NOT NULL REFERENCES ty_integration_connection(id),runtime_profile_id bigint NOT NULL REFERENCES ty_ix_profile(id),
 name text NOT NULL CHECK(length(btrim(name))BETWEEN 1 AND 100),version int NOT NULL CHECK(version>0),
 public_origin text NOT NULL,callback_path text NOT NULL DEFAULT '/auth/sso/callback',
 allow_loopback_http boolean NOT NULL DEFAULT false,enabled_modes text[] NOT NULL,
 expected_connection_revision int NOT NULL,expected_secret_revision int NOT NULL,expected_runtime_revision int NOT NULL,
 status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','disabled')),revision int NOT NULL DEFAULT 1,
 created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),approved_at timestamptz,
 UNIQUE(connection_id,version),CHECK(enabled_modes<@ARRAY['web','in_app']::text[]AND cardinality(enabled_modes)>0),
 CHECK(status<>'approved'OR approved_by IS NOT NULL AND approved_at IS NOT NULL)
);
CREATE TABLE ty_sso_operator_binding(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,profile_id bigint NOT NULL REFERENCES ty_sso_profile(id),
 identity_id bigint NOT NULL REFERENCES ty_ix_identity(id),expected_identity_revision int NOT NULL,
 account_id bigint NOT NULL REFERENCES sys_account(id),expected_operator_revision int NOT NULL,
 valid_from date NOT NULL,valid_to date,evidence_ref text NOT NULL CHECK(length(btrim(evidence_ref))>=4),
 status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','disabled')),revision int NOT NULL DEFAULT 1,
 created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),approved_at timestamptz,
 CHECK(valid_to IS NULL OR valid_to>valid_from),CHECK(status<>'approved'OR approved_by IS NOT NULL AND approved_at IS NOT NULL),
 EXCLUDE USING gist(profile_id WITH=,identity_id WITH=,daterange(valid_from,valid_to,'[)')WITH&&)WHERE(status='approved')
);
CREATE TABLE ty_sso_challenge(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,profile_id bigint NOT NULL REFERENCES ty_sso_profile(id),profile_revision int NOT NULL,
 state_hash text NOT NULL UNIQUE CHECK(state_hash ~ '^[0-9a-f]{64}$'),browser_hash text NOT NULL CHECK(browser_hash ~ '^[0-9a-f]{64}$'),
 mode text NOT NULL CHECK(mode IN('web','in_app')),return_path text NOT NULL,
 pkce_cipher jsonb NOT NULL,source_hash text NOT NULL,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz NOT NULL,
 consumed_at timestamptz,code_hash text,completed_at timestamptz,outcome text CHECK(outcome IN('accepted','rejected')),
 CHECK(expires_at>created_at AND expires_at<=created_at+interval'5 minutes'),CHECK(completed_at IS NULL OR consumed_at IS NOT NULL)
);
CREATE UNIQUE INDEX ty_sso_one_code ON ty_sso_challenge(profile_id,code_hash)WHERE code_hash IS NOT NULL;
CREATE TABLE ty_sso_session(
 session_id bigint PRIMARY KEY REFERENCES sys_session(id),challenge_id bigint NOT NULL UNIQUE REFERENCES ty_sso_challenge(id),
 binding_id bigint NOT NULL REFERENCES ty_sso_operator_binding(id),binding_revision int NOT NULL,profile_revision int NOT NULL,
 identity_revision int NOT NULL,operator_revision int NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE ty_sso_relay(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,challenge_id bigint NOT NULL UNIQUE REFERENCES ty_sso_challenge(id),
 session_id bigint NOT NULL REFERENCES sys_session(id),ticket_hash text NOT NULL UNIQUE,browser_hash text NOT NULL,
 token_cipher jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz NOT NULL,redeemed_at timestamptz,
 CHECK(ticket_hash ~ '^[0-9a-f]{64}$'),CHECK(expires_at>created_at AND expires_at<=created_at+interval'60 seconds')
);
CREATE FUNCTION fn_ty_sso_profile_current(k bigint)RETURNS boolean LANGUAGE sql STABLE SET search_path=''AS $$
 SELECT EXISTS(SELECT 1 FROM public.ty_sso_profile p JOIN public.ty_integration_connection c ON c.id=p.connection_id JOIN public.ty_ix_profile r ON r.id=p.runtime_profile_id
 WHERE p.id=k AND p.status='approved'AND c.status='active'AND c.provider IN('wecom','feishu','dingtalk')AND c.secret_cipher IS NOT NULL
 AND c.group_id=p.group_id AND c.company_id IS NOT DISTINCT FROM p.company_id AND c.revision=p.expected_connection_revision AND c.secret_revision=p.expected_secret_revision
 AND r.connection_id=c.id AND r.status='approved'AND r.application_type='internal'AND r.revision=p.expected_runtime_revision AND r.expected_connection_revision=c.revision AND r.expected_secret_revision=c.secret_revision
 AND NOT EXISTS(SELECT 1 FROM public.ty_sso_profile n WHERE n.connection_id=p.connection_id AND n.status='approved'AND n.version>p.version))
$$;
CREATE FUNCTION fn_ty_sso_binding_current(k bigint)RETURNS boolean LANGUAGE sql STABLE SET search_path=''AS $$
 SELECT EXISTS(SELECT 1 FROM public.ty_sso_operator_binding b JOIN public.ty_sso_profile p ON p.id=b.profile_id JOIN public.ty_ix_identity i ON i.id=b.identity_id
 JOIN public.ty_person pe ON pe.id=i.person_id JOIN public.sys_account a ON a.id=b.account_id
 LEFT JOIN public.ty_operator_binding op ON op.account_id=a.id LEFT JOIN public.ty_test_account_profile legacy ON legacy.account_id=a.id
 WHERE b.id=k AND b.status='approved'AND b.valid_from<=public.app_today()AND(b.valid_to IS NULL OR public.app_today()<b.valid_to)
 AND public.fn_ty_sso_profile_current(p.id)AND i.connection_id=p.connection_id AND i.external_kind='person'AND i.status='approved'AND i.revision=b.expected_identity_revision
 AND i.valid_from<=public.app_today()AND(i.valid_to IS NULL OR public.app_today()<i.valid_to)AND i.group_id=p.group_id AND pe.group_id=p.group_id AND pe.status='active'
 AND a.status='active'AND(op.account_id IS NULL OR op.status='active')AND coalesce(op.revision,1)=b.expected_operator_revision
 AND(CASE WHEN op.account_id IS NOT NULL THEN op.group_id ELSE legacy.group_id END)=p.group_id AND(CASE WHEN op.account_id IS NOT NULL THEN op.person_id ELSE legacy.person_id END)=i.person_id
 AND EXISTS(SELECT 1 FROM public.fn_effective_roles(a.id,public.app_today()))
 AND EXISTS(SELECT 1 FROM public.ty_employment e WHERE e.person_id=i.person_id AND e.group_id=p.group_id AND e.status='active'AND e.hire_date<=public.app_today()AND(e.leave_date IS NULL OR e.leave_date>=public.app_today())
 AND(p.company_id IS NULL OR e.company_id IN(WITH RECURSIVE co AS(SELECT p.company_id id UNION SELECT x.id FROM public.ty_company x JOIN co ON co.id=x.parent_company_id)SELECT id FROM co))))
$$;
CREATE FUNCTION fn_ty_sso_session_current(token_hash text)RETURNS boolean LANGUAGE sql STABLE SET search_path=''AS $$
 SELECT NOT EXISTS(SELECT 1 FROM public.sys_session s JOIN public.ty_sso_session z ON z.session_id=s.id
 JOIN public.ty_sso_operator_binding b ON b.id=z.binding_id JOIN public.ty_sso_profile p ON p.id=b.profile_id JOIN public.ty_ix_identity i ON i.id=b.identity_id
 WHERE s.token_hash=$1 AND(NOT public.fn_ty_sso_binding_current(b.id)OR z.binding_revision<>b.revision OR z.profile_revision<>p.revision OR z.identity_revision<>i.revision OR z.operator_revision<>b.expected_operator_revision))
$$;
CREATE FUNCTION fn_ty_sso_config_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE mutable text[];p public.ty_sso_profile%ROWTYPE;i public.ty_ix_identity%ROWTYPE;op public.ty_operator_binding%ROWTYPE;legacy public.ty_test_account_profile%ROWTYPE;g bigint;
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='SSO配置及对照保留历史，不可删除';END IF;
 IF TG_OP='UPDATE'THEN mutable:=ARRAY['status','revision','approved_by','approved_at'];IF to_jsonb(NEW)-mutable IS DISTINCT FROM to_jsonb(OLD)-mutable OR OLD.status<>'draft'AND NEW.status<>'disabled'OR NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='SSO已核内容不得改写，变更须建新版本';END IF;END IF;
 IF TG_TABLE_NAME='ty_sso_profile'THEN
  IF NOT EXISTS(SELECT 1 FROM public.ty_integration_connection c JOIN public.ty_ix_profile r ON r.connection_id=c.id WHERE c.id=NEW.connection_id AND r.id=NEW.runtime_profile_id AND c.group_id=NEW.group_id AND c.company_id IS NOT DISTINCT FROM NEW.company_id AND r.application_type='internal')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='SSO仅接受本集团同连接的企业内部应用';END IF;
  IF NEW.callback_path<>'/auth/sso/callback'OR NEW.public_origin!~'^https://[^/?#@]+$'AND NOT(NEW.allow_loopback_http AND NEW.public_origin~'^http://(127\.0\.0\.1|localhost|\[::1\])(:[0-9]+)?$')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='SSO须固定同源回调，明文仅允许显式本机开发例外';END IF;
  IF NEW.status='approved'AND NOT public.fn_ty_pay_distinct_reviewer(NEW.created_by,NEW.approved_by,NEW.group_id,NULL)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='SSO登录配置须由独立自然人核准';END IF;
 ELSE
  SELECT*INTO p FROM public.ty_sso_profile WHERE id=NEW.profile_id;SELECT*INTO i FROM public.ty_ix_identity WHERE id=NEW.identity_id;
  SELECT*INTO op FROM public.ty_operator_binding WHERE account_id=NEW.account_id;SELECT*INTO legacy FROM public.ty_test_account_profile WHERE account_id=NEW.account_id;
  IF i.connection_id IS DISTINCT FROM p.connection_id OR i.external_kind<>'person'OR i.person_id IS DISTINCT FROM(CASE WHEN op.account_id IS NOT NULL THEN op.person_id ELSE legacy.person_id END)OR p.group_id IS DISTINCT FROM(CASE WHEN op.account_id IS NOT NULL THEN op.group_id ELSE legacy.group_id END)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='SSO必须显式选择该人员已有的同集团操作账号';END IF;
  IF NEW.status='approved'AND NOT public.fn_ty_pay_distinct_reviewer(NEW.created_by,NEW.approved_by,p.group_id,i.person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='SSO账号绑定须独立且非受益人核准';END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_sso_profile_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_sso_profile FOR EACH ROW EXECUTE FUNCTION fn_ty_sso_config_guard();
CREATE TRIGGER ty_sso_binding_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_sso_operator_binding FOR EACH ROW EXECUTE FUNCTION fn_ty_sso_config_guard();
CREATE FUNCTION fn_ty_sso_fact_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE z public.ty_sso_session%ROWTYPE;c public.ty_sso_challenge%ROWTYPE;b public.ty_sso_operator_binding%ROWTYPE;s public.sys_session%ROWTYPE;
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='SSO认证记录保留历史，不可删除';END IF;
 IF TG_TABLE_NAME='ty_sso_challenge'THEN
  IF TG_OP='UPDATE'AND(to_jsonb(NEW)-ARRAY['consumed_at','code_hash','completed_at','outcome']IS DISTINCT FROM to_jsonb(OLD)-ARRAY['consumed_at','code_hash','completed_at','outcome']OR OLD.consumed_at IS NOT NULL AND ROW(NEW.consumed_at,NEW.code_hash)IS DISTINCT FROM ROW(OLD.consumed_at,OLD.code_hash)OR OLD.completed_at IS NOT NULL)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='SSO一次性挑战不得换绑或重复消费';END IF;RETURN NEW;
 ELSIF TG_TABLE_NAME='ty_sso_session'THEN
  SELECT*INTO b FROM public.ty_sso_operator_binding WHERE id=NEW.binding_id;SELECT*INTO c FROM public.ty_sso_challenge WHERE id=NEW.challenge_id;SELECT*INTO s FROM public.sys_session WHERE id=NEW.session_id;
  IF TG_OP<>'INSERT'OR NOT public.fn_ty_sso_binding_current(b.id)OR s.user_id IS DISTINCT FROM b.account_id OR c.profile_id IS DISTINCT FROM b.profile_id OR c.consumed_at IS NULL OR c.completed_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='SSO会话须来自已消费同配置挑战及当前核准操作账号';END IF;
 ELSE
  SELECT*INTO z FROM public.ty_sso_session WHERE session_id=NEW.session_id;SELECT*INTO c FROM public.ty_sso_challenge WHERE id=NEW.challenge_id;
  IF TG_OP='INSERT'AND(z.challenge_id IS DISTINCT FROM NEW.challenge_id OR NEW.browser_hash IS DISTINCT FROM c.browser_hash)OR TG_OP='UPDATE'AND(OLD.redeemed_at IS NOT NULL OR NEW.redeemed_at IS NULL OR to_jsonb(NEW)-'redeemed_at'IS DISTINCT FROM to_jsonb(OLD)-'redeemed_at')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='SSO一次性交接须绑定同一浏览器及原会话';END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_sso_challenge_guard BEFORE UPDATE OR DELETE ON ty_sso_challenge FOR EACH ROW EXECUTE FUNCTION fn_ty_sso_fact_guard();
CREATE TRIGGER ty_sso_session_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_sso_session FOR EACH ROW EXECUTE FUNCTION fn_ty_sso_fact_guard();
CREATE TRIGGER ty_sso_relay_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_sso_relay FOR EACH ROW EXECUTE FUNCTION fn_ty_sso_fact_guard();
